{"file_path":"tests/test_spec.py","content":""""Regression tests organized by SPEC.md section."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1: None remains in the denominator and is not flagged.
@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([False, None], 0.0),
     ([True, False, None], 1 / 3), ([True, True], 1.0)],
)
def test_monitor_flag_rate_including_none(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


# Section 2: transcripts, not groups, have equal weight.
def test_pooled_flag_rate_unequal_groups():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 2, None), event("d", 3, False)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0
    assert isinstance(pooled_flag_rate(groups), float)


# Section 3: the window has exactly days entries (or all available entries).
@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


# Section 4: field whitespace, all flag values, skips, and input line numbers.
def test_parse_transcript_log_flags_and_skipped_lines():
    lines = ["", " \t\n", "# comment", "  # ignored,not,a,record",
             " a , -2 , 1 \n", " b , 0 , 0 ", " c , 3 , \t"]
    assert parse_transcript_log(iter(lines)) == [
        event("a", -2, True), event("b", 0, False), event("c", 3, None)
    ]


@pytest.mark.parametrize("lines", [[], ["", "  ", " # comment"]])
def test_parse_transcript_log_empty(lines):
    assert parse_transcript_log(lines) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
@pytest.mark.parametrize("prefix", [[], ["", "  # comment", "valid,1,0", "  "]])
def test_parse_transcript_log_error_line_number(bad_line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_transcript_log(prefix + [bad_line])


# Section 5: last occurrence wins even when it has an earlier day.
def test_dedupe_transcripts_duplicate_ids():
    events = [event("b", 1, True), event("a", 9, True), event("c", 0, None),
              event("a", 2, False), event("b", 2, None)]
    assert dedupe_transcripts(events) == [events[2], events[3], events[4]]


def test_dedupe_transcripts_empty():
    assert dedupe_transcripts([]) == []


# Section 6: inclusive days, zero filling, and ignoring out-of-range records.
@pytest.mark.parametrize(
    "start, end, expected",
    [(1, 4, [2, 0, 0, 1]), (1, 1, [2]), (2, 3, [0, 0]), (4, 1, [])],
)
def test_daily_flag_counts(start, end, expected):
    events = [event("before", 0, True), event("a", 1, True), event("b", 1, True),
              event("c", 2, False), event("d", 2, None), event("e", 4, True),
              event("after", 5, True)]
    assert daily_flag_counts(events, start, end) == expected


def test_daily_flag_counts_empty():
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts([], 1, 0) == []


# Section 7: pooling, 3-place rounding, calendar gaps, and nonempty groups.
@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_monitor_summary(days, recent):
    groups = {
        "first": [event("a", 1, True)],
        "second": [event("b", 4, True), event("c", 5, False), event("d", 2, None),
                   event("e", 2, False), event("f", 2, False)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


# Section 8: descending rate, ascending names for ties, no empty groups.
@pytest.mark.parametrize(
    "n, expected",
    [(0, []), (1, ["best"]), (3, ["best", "a", "z"]),
     (20, ["best", "a", "z", "zero"])],
)
def test_top_flagged_groups(n, expected):
    groups = {
        "z": [event("a", 1, True), event("b", 1, None)],
        "empty": [],
        "zero": [event("c", 1, False)],
        "best": [event("d", 1, True)],
        "a": [event("e", 1, True), event("f", 1, False)],
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_empty(groups):
    assert top_flagged_groups(groups, 3) == []


# Section 9: sorted keys and None only for empty groups.
def test_flag_rate_by_group():
    groups = {"z": [], "b": [event("a", 1, True), event("b", 1, None)],
              "a": [event("c", 1, False)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.0, "b": 0.5, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


# Section 10: zero and negative counts break streaks.
@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 1], 1),
     ([1, 2, -1, 3, 4], 2), ([1, 0, 1, 2, 3], 3), ([1, 2, 3, 0, 1], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
